    "explanation": "Verified Answer: (C) Brachialis. The anterior compartment of the arm (biceps brachii, coracobrachialis, and brachialis) is supplied by the musculocutaneous nerve (C5–C7), which pierces coracobrachialis and continues past the elbow as the lateral cutaneous nerve of the forearm. Biceps is a powerful supinator of the flexed forearm, whereas brachialis is the primary flexor of the elbow in all positions. The radial nerve (C5–T1, posterior cord) supplies triceps in the axilla/spiral groove, pierces the lateral intermuscular septum, and divides in front of the lateral epicondyle into the superficial radial nerve (sensory) and posterior interosseous nerve (motor to deep extensors, piercing supinator). Mid-shaft humeral fracture causes wrist drop with spared triceps extension.",
